using AnalyticsReporting.Core;
namespace AnalyticsReporting.Worker; public sealed class JobWorker(IServiceScopeFactory scopes, ILogger<JobWorker> log) : BackgroundService { protected override async Task ExecuteAsync(CancellationToken ct) { while (!ct.IsCancellationRequested) { await using var scope = scopes.CreateAsyncScope(); var store = scope.ServiceProvider.GetRequiredService<IJobStore>(); var job = await store.LeaseNextAsync(ct); if (job is null) { await Task.Delay(1000, ct); continue; } try { await scope.ServiceProvider.GetRequiredService<CsvJobProcessor>().ProcessAsync(job, ct); } catch (OperationCanceledException) when (ct.IsCancellationRequested) { throw; } catch (Exception e) { job.Fail(e.Message); await store.SaveAsync(job, ct); log.LogError(e, "Job {JobId} failed", job.Id); } } } }
